package dev.switchboard.send;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.security.cert.X509Certificate;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.net.ssl.*;

/** Independent file-transfer core; shared by the Android app and JVM interop tests. */
public final class PeerEngine implements AutoCloseable {
    public static final String API="/api/switchboard/v1";
    public static final int PORT=53318;
    public static final long MAX=32L*1024*1024*1024;
    public interface Opener { InputStream open() throws Exception; }
    public static final class Source {
        public final String name,mime; public final long size; public final Opener opener;
        public Source(String n,String m,long s,Opener o){name=n;mime=m;size=s;opener=o;}
    }
    public static final class Item {
        public final String name,uri,mime; public final long size;
        public Item(String n,String u,String m,long s){name=n;uri=u;mime=m;size=s;}
    }
    public interface Sink {
        OutputStream stream() throws Exception; Item commit() throws Exception; void abort();
    }
    public interface Storage { Sink create(String name,String mime,long size) throws Exception; }
    public interface Events {
        void offer(Offer offer); void received(String peer,List<Item> items,boolean copy);
        void progress(String direction,String peer,String file,long completed,long total);
        void notice(String message);
    }
    public static final class Peer {
        public String id,name,platform,pin,address; public int port; public long seen; public boolean manual;
        public JSONObject json() throws Exception {return new JSONObject().put("id",id).put("name",name).put("platform",platform).put("port",port).put("certificateSha256",pin).put("version",1);}
        static Peer parse(JSONObject j,String address) throws Exception {
            Peer p=new Peer();p.id=j.getString("id");UUID.fromString(p.id);p.name=j.getString("name");p.platform=j.getString("platform");p.port=j.getInt("port");p.pin=j.getString("certificateSha256");p.address=address;p.seen=System.currentTimeMillis();
            if(j.optInt("version")!=1||p.name.length()<1||p.name.length()>64||p.platform.length()>32||p.port<1||p.port>65535||!p.pin.matches("[0-9a-fA-F]{64}"))throw new IOException("设备信息无效");return p;
        }
    }
    public static final class Decision {
        public final boolean accept,copy; public Decision(boolean a,boolean c){accept=a;copy=c;}
    }
    public static final class Offer {
        public final String peer,address;public final int count;public final long bytes;public final List<String> names;
        final CompletableFuture<Decision> decision=new CompletableFuture<>();
        Offer(String p,String a,int c,long b,List<String> n){peer=p;address=a;count=c;bytes=b;names=Collections.unmodifiableList(n);}
        public boolean pending(){return !decision.isDone();}
        public void accept(boolean copy){decision.complete(new Decision(true,copy));}
        public void reject(){decision.complete(new Decision(false,false));}
    }
    private static final class Meta {
        String id,name,mime,hash;long size;Source source;
        JSONObject json()throws Exception{return new JSONObject().put("id",id).put("name",name).put("mime",mime).put("sha256",hash).put("size",size);}
        static Meta parse(JSONObject j)throws Exception{Meta m=new Meta();m.id=j.getString("id");m.name=j.getString("name");m.size=j.getLong("size");m.mime=j.optString("mime","application/octet-stream");m.hash=j.getString("sha256");if(m.id.length()<1||m.id.length()>80||m.name.length()<1||m.name.length()>512||m.size<0||m.size>MAX||!m.hash.matches("[0-9a-fA-F]{64}"))throw new Failure(400,"文件信息无效");return m;}
    }
    private static final class Slot {Meta meta;String token=token();boolean writing;long bytes;Item item;}
    private static final class Session {String id=UUID.randomUUID().toString().replace("-",""),address,peer;boolean copy;Map<String,Slot> files=new LinkedHashMap<>();volatile long activity=System.currentTimeMillis();volatile boolean cancelled;}
    private static final class Failure extends IOException {final int status;Failure(int s,String m){super(m);status=s;}}
    private static final class Request {String method,path,address;Map<String,String> query=new HashMap<>();long length;InputStream body;}
    private static final SecureRandom RANDOM=new SecureRandom();
    private final SSLContext serverTls;private final Storage storage;private final Events events;private final boolean discovery;
    private final String bindAddress;private final int requestedPort;
    private final ConcurrentHashMap<String,Peer> peers=new ConcurrentHashMap<>();
    private final ExecutorService workers=new ThreadPoolExecutor(2,8,30,TimeUnit.SECONDS,new ArrayBlockingQueue<>(32),r->{Thread t=new Thread(r,"send-io");t.setDaemon(true);return t;});
    private final ScheduledExecutorService scheduler=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"send-discovery");t.setDaemon(true);return t;});
    private final Object receiveLock=new Object();private final AtomicLong progressAt=new AtomicLong();
    private SSLServerSocket server;private MulticastSocket udp;private volatile boolean running;private boolean reserved;private Session session;private Offer currentOffer;
    private volatile HttpsURLConnection outgoing;private final AtomicBoolean cancelled=new AtomicBoolean();
    public final Peer self;
    public PeerEngine(String id,String name,String platform,String fingerprint,SSLContext tls,Storage storage,Events events,int port,String bind,boolean discover){self=new Peer();self.id=id;self.name=name;self.platform=platform;self.pin=fingerprint;serverTls=tls;this.storage=storage;this.events=events;requestedPort=port;bindAddress=bind;discovery=discover;}
    public synchronized void start()throws Exception{
        if(running)return;
        IOException last=null;
        for(int i=0;i<8;i++){try{SSLServerSocket candidate=(SSLServerSocket)serverTls.getServerSocketFactory().createServerSocket();candidate.setEnabledProtocols(Arrays.stream(candidate.getSupportedProtocols()).filter(p->p.equals("TLSv1.2")||p.equals("TLSv1.3")).toArray(String[]::new));candidate.setReuseAddress(true);candidate.bind(new InetSocketAddress(bindAddress,requestedPort==0?0:requestedPort+i));server=candidate;break;}catch(IOException e){last=e;}}
        if(server==null)throw last;self.port=server.getLocalPort();running=true;
        Thread accept=new Thread(()->{while(running){try{SSLSocket socket=(SSLSocket)server.accept();try{workers.execute(()->handle(socket));}catch(RejectedExecutionException e){socket.close();}}catch(IOException e){if(running)events.notice("接收服务连接异常");}}},"send-listener");accept.setDaemon(true);accept.start();
        if(discovery){startUdp();scheduler.scheduleWithFixedDelay(()->{try{announce(true);}catch(Exception ignored){}expire();},0,5,TimeUnit.SECONDS);}
    }
    public void checkListener()throws Exception{Peer info=Peer.parse(new JSONObject(call("https://127.0.0.1:"+self.port+API+"/info","GET",null,self.pin,6000,null)),"127.0.0.1");if(!info.id.equals(self.id))throw new IOException("本机接收服务校验失败");}
    public List<Peer> peers(){List<Peer> result=new ArrayList<>();long now=System.currentTimeMillis();for(Peer p:peers.values())if(p.manual||now-p.seen<35000)result.add(p);result.sort(Comparator.comparing(p->p.name));return result;}
    public static List<String> addresses(){List<String> result=new ArrayList<>();try{Enumeration<NetworkInterface> all=NetworkInterface.getNetworkInterfaces();while(all.hasMoreElements()){NetworkInterface n=all.nextElement();if(!n.isUp()||n.isLoopback())continue;Enumeration<InetAddress> a=n.getInetAddresses();while(a.hasMoreElements()){InetAddress ip=a.nextElement();if(ip instanceof Inet4Address&&local(ip)&&!ip.isLinkLocalAddress())result.add(ip.getHostAddress());}}}catch(Exception ignored){}return result;}
    private static boolean local(InetAddress ip){return ip.isLoopbackAddress()||ip.isSiteLocalAddress()||ip.isLinkLocalAddress();}
    private void startUdp(){try{udp=new MulticastSocket(null);udp.setReuseAddress(true);udp.bind(new InetSocketAddress(PORT));InetSocketAddress group=new InetSocketAddress("224.0.0.167",PORT);for(String address:addresses())try{udp.joinGroup(group,NetworkInterface.getByInetAddress(InetAddress.getByName(address)));}catch(Exception ignored){}
        Thread listener=new Thread(()->{byte[] buffer=new byte[4096];while(running){try{DatagramPacket packet=new DatagramPacket(buffer,buffer.length);udp.receive(packet);if(!local(packet.getAddress()))continue;JSONObject j=new JSONObject(new String(packet.getData(),0,packet.getLength(),StandardCharsets.UTF_8));if(!"switchboard-send".equals(j.optString("kind")))continue;Peer p=Peer.parse(j.getJSONObject("peer"),packet.getAddress().getHostAddress());if(p.id.equals(self.id))continue;Peer previous=peers.get(p.id);p.manual=previous!=null&&previous.manual;peers.put(p.id,p);if(j.optBoolean("announce"))announce(false);}catch(Exception ignored){if(!running)break;}}},"send-udp");listener.setDaemon(true);listener.start();
        }catch(Exception e){events.notice("自动发现不可用，可使用设备地址连接");}}
    public synchronized void refreshDiscovery()throws Exception{if(udp!=null){for(String address:addresses())try{udp.joinGroup(new InetSocketAddress("224.0.0.167",PORT),NetworkInterface.getByInetAddress(InetAddress.getByName(address)));}catch(Exception ignored){}}announce(true);}
    public void announce(boolean announce)throws Exception{byte[] data=new JSONObject().put("kind","switchboard-send").put("peer",self.json()).put("announce",announce).toString().getBytes(StandardCharsets.UTF_8);for(String address:addresses()){try(MulticastSocket socket=new MulticastSocket(new InetSocketAddress(address,0))){socket.setNetworkInterface(NetworkInterface.getByInetAddress(InetAddress.getByName(address)));socket.setTimeToLive(1);socket.send(new DatagramPacket(data,data.length,InetAddress.getByName("224.0.0.167"),PORT));}catch(Exception ignored){}}}
    private void expire(){synchronized(receiveLock){if(session!=null&&System.currentTimeMillis()-session.activity>180000){session.cancelled=true;session=null;reserved=false;events.notice("接收已超时");}}for(Peer p:peers.values())if(!p.manual&&System.currentTimeMillis()-p.seen>60000)peers.remove(p.id);}
    private void handle(SSLSocket socket){try(SSLSocket s=socket){if(!local(s.getInetAddress()))return;s.setSoTimeout(30000);try{s.startHandshake();}catch(Exception handshake){events.notice("加密连接失败 · "+handshake.getClass().getSimpleName());throw handshake;}InputStream in=new BufferedInputStream(s.getInputStream(),131072);OutputStream out=new BufferedOutputStream(s.getOutputStream(),16384);try{Request r=request(in,s.getInetAddress().getHostAddress());
            if(r.path.equals(API+"/info")&&r.method.equals("GET"))reply(out,200,self.json().toString());
            else if(r.path.equals(API+"/prepare")&&r.method.equals("POST"))reply(out,200,prepare(r).toString());
            else if(r.path.equals(API+"/upload")&&r.method.equals("POST")){upload(r);reply(out,200,"");}
            else if(r.path.equals(API+"/cancel")&&r.method.equals("POST")){synchronized(receiveLock){if(session!=null&&session.address.equals(r.address)&&session.id.equals(r.query.get("session"))){session.cancelled=true;session=null;reserved=false;}}reply(out,200,"");}
            else reply(out,404,"{}");
        }catch(Failure e){reply(out,e.status,new JSONObject().put("error",e.getMessage()).toString());}catch(Exception e){try{reply(out,500,"{\"error\":\"传输失败\"}");}catch(Exception ignored){}}out.flush();}catch(Exception ignored){}}
    private static Request request(InputStream in,String address)throws Exception{String first=line(in,4096);if(first==null)throw new EOFException();String[] parts=first.split(" ");if(parts.length!=3)throw new Failure(400,"请求无效");Request r=new Request();r.method=parts[0];r.address=address;r.body=in;String[] uri=parts[1].split("\\?",2);r.path=uri[0];if(uri.length==2)for(String pair:uri[1].split("&")){String[] item=pair.split("=",2);r.query.put(URLDecoder.decode(item[0],"UTF-8"),item.length==2?URLDecoder.decode(item[1],"UTF-8"):"");}int headers=0;while(true){String h=line(in,8192);if(h==null)throw new EOFException();headers+=h.length();if(headers>16384)throw new Failure(413,"请求头过大");if(h.isEmpty())break;int colon=h.indexOf(':');if(colon<0)throw new Failure(400,"请求无效");String key=h.substring(0,colon).trim().toLowerCase(Locale.ROOT);String value=h.substring(colon+1).trim();if(key.equals("content-length"))r.length=Long.parseLong(value);if(key.equals("transfer-encoding"))throw new Failure(400,"需要文件长度");}if(r.length<0||r.length>MAX)throw new Failure(413,"文件过大");return r;}
    private static String line(InputStream in,int limit)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int c;while((c=in.read())!=-1){if(c=='\n')break;if(c!='\r')b.write(c);if(b.size()>limit)throw new Failure(413,"请求过大");}return c==-1&&b.size()==0?null:b.toString("UTF-8");}
    private static void reply(OutputStream out,int status,String body)throws IOException{byte[] data=body.getBytes(StandardCharsets.UTF_8);String reason=status==200?"OK":status==403?"Forbidden":status==409?"Conflict":"Error";out.write(("HTTP/1.1 "+status+" "+reason+"\r\nContent-Type: application/json; charset=utf-8\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(data);}
    private static String body(Request r)throws Exception{if(r.length>262144)throw new Failure(413,"文件列表过大");byte[] bytes=new byte[(int)r.length];int pos=0;while(pos<bytes.length){int n=r.body.read(bytes,pos,bytes.length-pos);if(n<0)throw new EOFException();pos+=n;}return new String(bytes,StandardCharsets.UTF_8);}
    private JSONObject prepare(Request r)throws Exception{JSONObject json=new JSONObject(body(r));Peer sender=Peer.parse(json.getJSONObject("sender"),r.address);JSONArray files=json.getJSONArray("files");if(files.length()<1||files.length()>512)throw new Failure(400,"文件数量无效");Session next=new Session();next.address=r.address;next.peer=sender.name;long total=0;for(int i=0;i<files.length();i++){Meta m=Meta.parse(files.getJSONObject(i));if(next.files.containsKey(m.id))throw new Failure(400,"文件编号重复");Slot slot=new Slot();slot.meta=m;next.files.put(m.id,slot);total+=m.size;if(total>MAX)throw new Failure(413,"单次传输超过 32 GB");}Offer offer=new Offer(sender.name,r.address,files.length(),total,next.files.values().stream().map(item->item.meta.name).collect(java.util.stream.Collectors.toList()));synchronized(receiveLock){if(reserved)throw new Failure(409,"正在接收其他文件");reserved=true;currentOffer=offer;}boolean retained=false;try{events.offer(offer);Decision decision;try{decision=offer.decision.get(120,TimeUnit.SECONDS);}catch(TimeoutException e){throw new Failure(403,"接收请求已超时");}if(!decision.accept)throw new Failure(403,"对方已拒绝");next.copy=decision.copy;synchronized(receiveLock){session=next;currentOffer=null;retained=true;}JSONObject tokens=new JSONObject();for(Map.Entry<String,Slot> file:next.files.entrySet())tokens.put(file.getKey(),file.getValue().token);return new JSONObject().put("session",next.id).put("files",tokens);}finally{offer.reject();synchronized(receiveLock){if(!retained&&currentOffer==offer){reserved=false;currentOffer=null;}}}}
    private void upload(Request r)throws Exception{Session s;Slot slot;synchronized(receiveLock){s=session;if(s==null||!s.id.equals(r.query.get("session"))||!s.address.equals(r.address))throw new Failure(403,"传输会话无效");slot=s.files.get(r.query.get("file"));if(slot==null||!constant(slot.token,r.query.get("token")))throw new Failure(403,"传输凭据无效");if(slot.writing||slot.item!=null)throw new Failure(409,"文件已在接收");if(r.length!=slot.meta.size)throw new Failure(400,"文件长度不一致");slot.writing=true;}Sink sink=null;boolean committed=false;try{sink=storage.create(safeName(slot.meta.name),slot.meta.mime,slot.meta.size);MessageDigest digest=MessageDigest.getInstance("SHA-256");try(OutputStream out=sink.stream()){byte[] buffer=new byte[131072];long count=0;while(count<r.length){if(!running||s.cancelled)throw new IOException("已取消");int n=r.body.read(buffer,0,(int)Math.min(buffer.length,r.length-count));if(n<0)throw new EOFException();out.write(buffer,0,n);digest.update(buffer,0,n);count+=n;slot.bytes=count;s.activity=System.currentTimeMillis();progress("接收",s.peer,slot.meta.name,totalBytes(s),totalSize(s),false);}}if(!hex(digest.digest()).equalsIgnoreCase(slot.meta.hash))throw new Failure(422,"文件校验失败");if(s.cancelled)throw new IOException("已取消");Item saved=sink.commit();committed=true;List<Item> finished=null;synchronized(receiveLock){slot.item=saved;slot.bytes=slot.meta.size;boolean done=true;for(Slot item:s.files.values())if(item.item==null)done=false;if(done){finished=new ArrayList<>();for(Slot item:s.files.values())finished.add(item.item);if(session==s){session=null;reserved=false;}}}if(finished!=null){progress("接收",s.peer,"已完成",totalSize(s),totalSize(s),true);events.received(s.peer,finished,s.copy);}}catch(Exception error){events.notice("接收失败 · "+(error.getMessage()==null?error.getClass().getSimpleName():error.getMessage()));throw error;}finally{if(!committed){if(sink!=null)sink.abort();synchronized(receiveLock){slot.writing=false;slot.bytes=0;}}}}
    private static long totalBytes(Session s){long n=0;for(Slot slot:s.files.values())n+=slot.bytes;return n;}
    private static long totalSize(Session s){long n=0;for(Slot slot:s.files.values())n+=slot.meta.size;return n;}
    private void progress(String direction,String peer,String file,long bytes,long total,boolean force){long now=System.nanoTime(),last=progressAt.get();if(!force&&now-last<125000000)return;progressAt.set(now);events.progress(direction,peer,file,bytes,total);}
    public Peer addPeer(String address)throws Exception{String cleaned=address.trim().replace("https://","");if(!cleaned.matches("[0-9]{1,3}(\\.[0-9]{1,3}){3}(:[0-9]{1,5})?"))throw new IOException("地址格式：192.168.1.10:53318");String[] parts=cleaned.split(":");String ip=parts[0];int port=parts.length>1?Integer.parseInt(parts[1]):PORT;if(!local(InetAddress.getByName(ip))||port<1||port>65535)throw new IOException("设备地址无效");final String[] observed={null};JSONObject json=new JSONObject(call("https://"+ip+":"+port+API+"/info","GET",null,null,6000,value->observed[0]=value));Peer p=Peer.parse(json,ip);if(!p.pin.equalsIgnoreCase(observed[0])||p.port!=port)throw new IOException("设备证书无效");if(p.id.equals(self.id))throw new IOException("这是本机地址");p.manual=true;peers.put(p.id,p);return p;}
    private interface Observed {void hash(String value);}
    private static SSLContext clientTls(String pin,Observed observed)throws Exception{TrustManager[] trust={new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] chain,String auth){}public void checkServerTrusted(X509Certificate[] chain,String auth)throws java.security.cert.CertificateException{try{if(chain.length==0)throw new Exception();chain[0].checkValidity();String hash=hex(MessageDigest.getInstance("SHA-256").digest(chain[0].getEncoded()));if(observed!=null)observed.hash(hash);if(pin!=null&&!pin.equalsIgnoreCase(hash))throw new Exception();}catch(Exception e){throw new java.security.cert.CertificateException("设备证书不一致");}}}};SSLContext context=SSLContext.getInstance("TLS");context.init(null,trust,RANDOM);return context;}
    private static HttpsURLConnection connection(String url,String pin,int timeout,Observed observed)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(url).openConnection(Proxy.NO_PROXY);c.setSSLSocketFactory(clientTls(pin,observed).getSocketFactory());c.setHostnameVerifier((host,session)->true);c.setInstanceFollowRedirects(false);c.setConnectTimeout(6000);c.setReadTimeout(timeout);c.setRequestProperty("Connection","close");return c;}
    private String call(String url,String method,byte[] data,String pin,int timeout,Observed observed)throws Exception{HttpsURLConnection c=connection(url,pin,timeout,observed);outgoing=c;try{c.setRequestMethod(method);if(data!=null){c.setDoOutput(true);c.setFixedLengthStreamingMode(data.length);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(data);}}int status=c.getResponseCode();if(status!=200)throw new Failure(status,status==403?"对方拒绝或接收请求超时":status==409?"对方正在接收其他文件":"传输请求失败");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>262144)throw new IOException("设备响应过大");out.write(buffer,0,n);}return out.toString("UTF-8");}}finally{if(outgoing==c)outgoing=null;c.disconnect();}}
    public void cancelReceive(){synchronized(receiveLock){if(currentOffer!=null)currentOffer.reject();if(session!=null)session.cancelled=true;session=null;reserved=false;}}
    public void cancelSend(){cancelled.set(true);HttpsURLConnection c=outgoing;if(c!=null)c.disconnect();}
    public void send(Peer peer,List<Source> sources)throws Exception{if(sources.size()<1||sources.size()>512||!local(InetAddress.getByName(peer.address)))throw new IOException("文件或设备无效");cancelled.set(false);String root="https://"+peer.address+":"+peer.port+API;Peer current=Peer.parse(new JSONObject(call(root+"/info","GET",null,peer.pin,6000,null)),peer.address);if(!current.id.equals(peer.id))throw new IOException("设备身份已变化");List<Meta> files=new ArrayList<>();long total=0;for(Source source:sources){if(cancelled.get())throw new IOException("已取消");progress("发送",peer.name,"校验中 · "+source.name,0,0,true);Meta m=new Meta();m.id=UUID.randomUUID().toString().replace("-","");m.name=source.name;m.mime=source.mime;m.source=source;MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=source.opener.open()){if(in==null)throw new IOException("文件无法读取");byte[] buffer=new byte[131072];int n;while((n=in.read(buffer))!=-1){if(cancelled.get())throw new IOException("已取消");hash.update(buffer,0,n);m.size+=n;if(m.size>MAX)throw new IOException("文件超过 32 GB");}}m.hash=hex(hash.digest());total+=m.size;if(total>MAX)throw new IOException("单次传输超过 32 GB");files.add(m);}JSONArray metadata=new JSONArray();for(Meta m:files)metadata.put(m.json());String sessionId=null;boolean done=false;long sent=0;try{progress("发送",peer.name,"等待接收",0,total,true);JSONObject prepared=new JSONObject(call(root+"/prepare","POST",new JSONObject().put("sender",self.json()).put("files",metadata).toString().getBytes(StandardCharsets.UTF_8),peer.pin,135000,null));sessionId=prepared.getString("session");JSONObject tokens=prepared.getJSONObject("files");for(Meta m:files){if(cancelled.get())throw new IOException("已取消");String url=root+"/upload?session="+URLEncoder.encode(sessionId,"UTF-8")+"&file="+m.id+"&token="+URLEncoder.encode(tokens.getString(m.id),"UTF-8");HttpsURLConnection c=connection(url,peer.pin,30000,null);outgoing=c;try{c.setRequestMethod("POST");c.setDoOutput(true);c.setFixedLengthStreamingMode(m.size);c.setRequestProperty("Content-Type","application/octet-stream");long copied=0;try(InputStream in=m.source.opener.open();OutputStream out=c.getOutputStream()){byte[] buffer=new byte[131072];int n;while((n=in.read(buffer))!=-1){if(cancelled.get())throw new IOException("已取消");copied+=n;if(copied>m.size)throw new IOException("发送期间文件已变化");out.write(buffer,0,n);progress("发送",peer.name,m.name,sent+copied,total,false);}if(copied!=m.size)throw new IOException("发送期间文件已变化");}int status=c.getResponseCode();if(status!=200)throw new IOException(status==422?"文件校验失败":"文件未能发送完成");sent+=m.size;}finally{outgoing=null;c.disconnect();}}done=true;progress("发送",peer.name,"已完成",total,total,true);}finally{if(!done&&sessionId!=null)try{call(root+"/cancel?session="+URLEncoder.encode(sessionId,"UTF-8"),"POST",new byte[0],peer.pin,3000,null);}catch(Exception ignored){}}}
    public static String safeName(String name){String[] pieces=name.replace('\\','/').split("/");String value=(pieces.length==0?"file":pieces[pieces.length-1]).replaceAll("[\\x00-\\x1f<>:\"/\\\\|?*]","_").trim().replaceAll("[. ]+$","");if(value.isEmpty())value="file";if(value.length()>180)value=value.substring(0,180);if(value.split("\\.")[0].matches("(?i)CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9]"))value="_"+value;return value;}
    public static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    private static String token(){byte[] data=new byte[24];RANDOM.nextBytes(data);return hex(data);}
    private static boolean constant(String a,String b){return b!=null&&a.length()==b.length()&&MessageDigest.isEqual(a.getBytes(StandardCharsets.US_ASCII),b.getBytes(StandardCharsets.US_ASCII));}
    @Override public synchronized void close(){running=false;cancelSend();synchronized(receiveLock){if(currentOffer!=null)currentOffer.reject();if(session!=null)session.cancelled=true;}try{if(server!=null)server.close();}catch(Exception ignored){}if(udp!=null)udp.close();scheduler.shutdownNow();workers.shutdownNow();}
}
